package br.com.onda;
import android.app.*;import android.content.*;import android.content.res.AssetFileDescriptor;import android.net.Uri;import android.os.*;import android.service.notification.StatusBarNotification;import android.widget.*;import androidx.core.content.FileProvider;
import java.io.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;
import org.junit.*;import static org.junit.Assert.*;import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;
@androidx.media3.common.util.UnstableApi
public class ChapterExportBackgroundTest {
 private final Instrumentation ins=getInstrumentation();private final Context c=ins.getTargetContext();private ChapterExportActivity screen;private File source,output;private Uri uri,target;private String stamp;private AudioChapterStore.Data markers;
 private final CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);private final AtomicInteger calls=new AtomicInteger();private boolean gateAtCopy;
 private interface Check{boolean ready()throws Exception;}
 private void waitFor(Check check)throws Exception{for(int i=0;i<400;i++){boolean[] ready={false};ins.runOnMainSync(()->{try{ready[0]=check.ready();}catch(Exception error){throw new RuntimeException(error);}});if(ready[0])return;Thread.sleep(50);}ChapterExportService.Snapshot state=ChapterExportService.state(c);fail("Timed out: "+(state==null?"no conversion":state.phase+" "+state.message));}
 private Object field(Object owner,String name)throws Exception{java.lang.reflect.Field f=owner.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(owner);}
 private ChapterExportService service()throws Exception{java.lang.reflect.Field f=ChapterExportService.class.getDeclaredField("live");f.setAccessible(true);return (ChapterExportService)f.get(null);}
 private void shell(String command)throws Exception{try(ParcelFileDescriptor p=ins.getUiAutomation().executeShellCommand(command);InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(p)){while(in.read()!=-1){}}}
 private StatusBarNotification notification(){for(StatusBarNotification n:((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).getActiveNotifications())if(n.getId()==ChapterExportService.NOTICE)return n;return null;}
 private void gate()throws IOException{entered.countDown();try{if(!release.await(20,TimeUnit.SECONDS))throw new IOException("Test gate timeout");}catch(InterruptedException error){Thread.currentThread().interrupt();throw new InterruptedIOException("Cancelado");}}
 @Before public void before()throws Exception{
  File folder=new File(c.getCacheDir(),"shares");folder.mkdirs();File wave=AudioTestFixtures.collection(c);source=new File(folder,"export-source-"+UUID.randomUUID()+".wav");assertTrue(wave.renameTo(source));output=File.createTempFile("export-target-",".mp3",folder);uri=Uri.fromFile(source);target=FileProvider.getUriForFile(c,c.getPackageName()+".share",output);stamp=AudioChapterStore.stamp(c,uri);
  markers=new AudioChapterStore.Data(96600,Arrays.asList(new AudioChapterStore.Chapter(0,"Antes"),new AudioChapterStore.Chapter(34000,"Trecho teste"),new AudioChapterStore.Chapter(37000,"Depois")));AudioChapterStore.save(c,uri,stamp,markers);Mp3Quality.save(c,320);
  ChapterExportService.converter=(context,job,destination,control)->{calls.incrementAndGet();if(!gateAtCopy)gate();ChapterExportTask.run(context,job,destination,new ChapterExportTask.Control(){public void check()throws IOException{control.check();}public void progress(long at,long total){control.progress(at,total);}public void stage(String message){control.stage(message);if(gateAtCopy&&message.startsWith("Salvando"))try{gate();}catch(IOException error){throw new GateFailure(error);}}});};
 }
 private static class GateFailure extends RuntimeException{GateFailure(IOException error){super(error);}}
 private void start(Uri destination)throws Exception{
  Intent input=new Intent(c,ChapterExportActivity.class).putExtra("source",uri.toString()).putExtra("stamp",stamp).putExtra("name","Trecho teste").putExtra("start",34000L).putExtra("end",37000L).putExtra("duration",96600L).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
  screen=(ChapterExportActivity)ins.startActivitySync(input);ins.runOnMainSync(()->screen.onActivityResult(71,Activity.RESULT_OK,new Intent().setData(destination)));ins.runOnMainSync(()->{try{java.lang.reflect.Field pending=ChapterExportActivity.class.getDeclaredField("pending");pending.setAccessible(true);pending.set(screen,null);java.lang.reflect.Method m=ChapterExportActivity.class.getDeclaredMethod("convert",Uri.class);m.setAccessible(true);m.invoke(screen,destination);}catch(Exception error){throw new RuntimeException(error);}});assertTrue(entered.await(10,TimeUnit.SECONDS));waitFor(()->service()!=null&&notification()!=null);
 }
 @After public void after()throws Exception{release.countDown();shell("input keyevent 224");shell("wm dismiss-keyguard");ins.runOnMainSync(()->{c.stopService(new Intent(c,ChapterExportService.class));if(screen!=null)screen.finish();});waitFor(()->service()==null);ChapterExportService.converter=ChapterExportTask::run;((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).cancel(ChapterExportService.NOTICE);Mp3Quality.save(c,192);source.delete();output.delete();ins.waitForIdleSync();}
 @Test public void realMp3CompletesScreenOffAfterExportActivityIsDestroyed()throws Exception{
  byte[] original=java.nio.file.Files.readAllBytes(source.toPath());start(target);PowerManager.WakeLock wake=(PowerManager.WakeLock)field(service(),"wake");assertTrue(wake.isHeld());assertTrue((notification().getNotification().flags&Notification.FLAG_ONGOING_EVENT)!=0);
  if(Build.VERSION.SDK_INT>=29)assertEquals(Build.VERSION.SDK_INT>=35?android.content.pm.ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PROCESSING:android.content.pm.ServiceInfo.FOREGROUND_SERVICE_TYPE_DATA_SYNC,service().getForegroundServiceType());
  ChapterExportJob job=ChapterExportService.state(c).job;Mp3Quality.save(c,128);assertFalse(ChapterExportService.start(c,job));shell("input keyevent 3");waitFor(()->!(Boolean)field(screen,"started"));shell("input keyevent 223");ins.runOnMainSync(()->screen.finish());waitFor(()->screen.isDestroyed());assertTrue(wake.isHeld());assertFalse(((PowerManager)c.getSystemService(Context.POWER_SERVICE)).isInteractive());release.countDown();
  waitFor(()->"done".equals(ChapterExportService.state(c).phase)&&service()==null);assertFalse(wake.isHeld());assertEquals(1,calls.get());assertEquals(320,ChapterExportService.state(c).job.bitrate);assertTrue(new ChapterExportTest().decodedRms(output,3000)>100);assertTrue(output.length()>100000);assertArrayEquals(original,java.nio.file.Files.readAllBytes(source.toPath()));
  shell("input keyevent 224");shell("wm dismiss-keyguard");screen=(ChapterExportActivity)ins.startActivitySync(job.screen(c).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitFor(()->target.equals(field(screen,"saved"))&&screen.hasWindowFocus());ins.waitForIdleSync();Thread.sleep(250);ins.runOnMainSync(()->{try{assertTrue(((Button)field(screen,"share")).isShown());assertFalse((Boolean)field(screen,"busy"));}catch(Exception error){throw new RuntimeException(error);}});
  android.graphics.Bitmap image=ins.getUiAutomation().takeScreenshot();assertNotNull(image);try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"chapter-export-background.png"))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}finally{image.recycle();}
 }
 @Test public void cancellationBeforeCopyRemovesValidatedPartialDestination()throws Exception{gateAtCopy=true;byte[] original=java.nio.file.Files.readAllBytes(source.toPath());start(target);PowerManager.WakeLock wake=(PowerManager.WakeLock)field(service(),"wake");shell("input keyevent 3");notification().getNotification().actions[0].actionIntent.send();waitFor(()->!ChapterExportService.state(c).running&&service()==null);assertEquals("cancelled",ChapterExportService.state(c).phase);assertFalse(wake.isHeld());assertTrue(!output.exists()||output.length()==0);assertArrayEquals(original,java.nio.file.Files.readAllBytes(source.toPath()));}
 @Test public void aliasOfOriginalIsNeverTruncatedOrDeleted()throws Exception{Uri alias=FileProvider.getUriForFile(c,c.getPackageName()+".share",source);byte[] original=java.nio.file.Files.readAllBytes(source.toPath());start(alias);release.countDown();waitFor(()->"error".equals(ChapterExportService.state(c).phase)&&service()==null);assertArrayEquals(original,java.nio.file.Files.readAllBytes(source.toPath()));assertTrue(source.exists());}
 @Test public void nonemptyDestinationIsNeverOverwritten()throws Exception{byte[] original={1,2,3,4,5};java.nio.file.Files.write(output.toPath(),original);start(target);release.countDown();waitFor(()->"error".equals(ChapterExportService.state(c).phase)&&service()==null);assertArrayEquals(original,java.nio.file.Files.readAllBytes(output.toPath()));}
 @Test public void changedChapterBoundsFailWithoutModifyingOriginal()throws Exception{byte[] original=java.nio.file.Files.readAllBytes(source.toPath());start(target);AudioChapterStore.save(c,uri,stamp,ChapterEdits.full(96600));release.countDown();waitFor(()->"error".equals(ChapterExportService.state(c).phase)&&service()==null);assertTrue(ChapterExportService.state(c).message.contains("horários"));assertArrayEquals(original,java.nio.file.Files.readAllBytes(source.toPath()));assertTrue(!output.exists()||output.length()==0);}
}
